from src.models.item import Item
from src.api.routes.users import get_user


ITEMS = [
    Item(id=1, owner_id=1, name="Notebook"),
    Item(id=2, owner_id=1, name="Pen"),
    Item(id=3, owner_id=2, name="Backpack"),
]


def list_items(include_archived: bool = False) -> list[dict]:
    return [
        item.as_dict()
        for item in ITEMS
        if include_archived or not item.archived
    ]


def get_item(item_id: int) -> dict | None:
    for item in ITEMS:
        if item.id == item_id:
            return item.as_dict()
    return None


def favorite_item(user_id: int, item_id: int) -> dict:
    user = get_user(user_id)
    if not user:
        return {"ok": False, "reason": "user_not_found"}
    if not user.owns_item(item_id):
        return {"ok": False, "reason": "not_owned"}
    if item_id not in user.favorite_item_ids:
        user.favorite_item_ids.append(item_id)
    return {"ok": True}


def unfavorite_item(user_id: int, item_id: int) -> dict:
    user = get_user(user_id)
    if not user:
        return {"ok": False, "reason": "user_not_found"}
    if item_id in user.favorite_item_ids:
        user.favorite_item_ids.remove(item_id)
    return {"ok": True}


def list_favorite_items(user_id: int) -> list[dict]:
    user = get_user(user_id)
    if not user:
        return []
    return [
        item.as_dict()
        for item in ITEMS
        if item.id in user.favorite_item_ids
    ]

